"""Exercise successful activation on generated cohorts and stream staging on generated bytes."""
import copy
from hashlib import sha256
import importlib.util
import json
from pathlib import Path
import shlex
import sys
from unittest.mock import patch

from activate import RUN, ROOT, pin, activate, require_grant
from bien_nhan import atomic, fingerprint, read_pin, ref, Blocked
from nguon import validate_aggregate_plan
import activate as activation
import main as launch


def main():
    target = RUN / 'fixture-activation-003'
    target.mkdir(exist_ok=False)
    def write(name, value):
        atomic(target / name, value)
        return pin(target / name)
    cases = {}
    cohorts = {}
    runtimes = {}
    independent = {}
    inventory = {}
    for dataset, n in [('RE2-TT', 60), ('Nezha-OB', 34)]:
        members = [sha256(('SYNTHETIC-013-' + dataset + str(i)).encode()).hexdigest() for i in range(n)]
        cohorts[dataset] = dict(members_locked_sha256=members)
        inventory[dataset] = ['fixture-service']
        rows = {}
        for member in members:
            row = dict(member_sha256=member, files={'metrics.parquet': dict(path='fixture/metrics.parquet', sha256='a' * 64, bytes=7)})
            row.update(dict(t=1000, ce_history='verified') if dataset == 'RE2-TT' else dict(t_ns=1000000000000, trace_guard_s=0))
            rows['test-' + member[:10]] = row
        rt = dict(dataset=dataset, inventory=inventory[dataset], cases=rows)
        source = dict(schema='P7-CASE-SOURCE-001', dataset=dataset,
                      cases_by_member={row['member_sha256']: row for row in rows.values()})
        runtimes[dataset] = write(dataset + '-runtime.json', rt)
        independent[dataset] = write(dataset + '-independent.json', source)
        cases[dataset] = rows
    cohort_ref = write('cohort.json', dict(cohorts=cohorts, inventory=inventory))
    policy_ref = write('failure-policy.json', dict(schema='T054-FAILURE-POLICY-1', scope='CANDIDATE', main_allowed=False, code_evidence=[]))
    host_policy = dict(workers=1, monitor={}, budget={}, code_pins={}, sensitivity_decision_ref=None,
                       timeout_s={'main_slot': 600, 'C-d3': 60}, environment_sha256={'main': 'a' * 64})
    hosts = ('ec2_1', 'ec2_2', 'local')
    contract_ref = write('contract.json', dict(schema='T054-DISPATCH-CONTRACT-1', hosts={h: host_policy for h in hosts},
                         failure_policy_candidate_ref=policy_ref, baseline_config_sha256={}))
    protocol = dict(status='CANDIDATE_NOT_LOCKED', source_code={}, cohorts_source=cohort_ref,
                    dispatch_contract_ref=contract_ref, configurations={'M1': {'sha256': fingerprint({})}}, allowed_hosts=list(hosts))
    pp = write('protocol-candidate.json', protocol)
    source_ref = write('author-source.json', {'schema': 'SYNTHETIC_ONLY'})
    bundle_ref = write('source-bundle.json', dict(runtime_refs=runtimes, independent_source_refs=independent,
                                               failure_policy_ref=policy_ref, author_source_ref=source_ref))
    for i, host in enumerate(hosts):
        oid, row = list(cases['RE2-TT'].items())[i]
        slot = dict(dataset='RE2-TT', opaque_id=oid, member_sha256=row['member_sha256'], arm='M1', view='main', seed=None,
                    config_sha256=fingerprint({}), environment_sha256='a' * 64, source_sha256=fingerprint(row), window={'t': 1000, 'half_width_s': 300})
        job = dict(slot=slot, kind='m1', evaluation_mode='test', config={}, code_pins={}, m1_contract=None,
                   protocol_ref=pp, failure_policy_ref=policy_ref, timeout_s=600)
        write('prepared/' + host + '-plan.json', dict(mode='test', schema='T054-PLAN-1', host_role=host, workers=1,
             monitor={}, budget={}, ce_support=[], jobs=[job], protocol_ref=pp, sensitivity_decision_ref=None))
    write('prepared/aggregate-plan.json', dict(mode='test', host_role='aggregate', jobs=[], ce_support=[]))
    decision = write('synthetic-permission.json', dict(scope='GENERATED_FIXTURE_ONLY_NOT_A_USER_GRANT'))
    grant = dict(g3=True, test_grant=True, main_dispatch=True, materialize_source_grant=True,
                 transfer_test_grant=True, score_grant=True, source=decision,
                 approved_candidate_protocol_sha256=pp['sha256'], approved_source_bundle_sha256=bundle_ref['sha256'],
                 main_operating_policy_approved=True, RE3_preparation_disposition='OPEN_ACCEPTED_FOR_MAIN_ONLY')
    gp = write('synthetic-grant.json', grant)
    manifest_ref = write('manifest.json', {'schema': 'GENERATED_FIXTURE_ONLY', 'outputs': {}})
    grant['approved_preparation_manifest_sha256'] = manifest_ref['sha256']
    gp = write('synthetic-grant-with-manifest.json', grant)
    checks = []
    with patch.object(activation, 'RUN', target):
        for flag in ('g3', 'test_grant', 'main_dispatch', 'materialize_source_grant', 'transfer_test_grant', 'score_grant'):
            try:
                require_grant(dict(grant, **{flag: False}))
            except Blocked:
                checks.append('missing_' + flag)
            else:
                raise AssertionError(flag)
        result = activate(gp)
        assert activate(gp) == result
        locked = read_pin(result['protocol'])
        aggregate = read_pin(result['aggregate'])
        validate_aggregate_plan(aggregate, locked)
        assert len(aggregate['jobs']) == 3
        checks.extend(['activation_positive_generated_cohorts', 'activation_idempotent_exact_grant', 'locked_validator_positive'])
        # Opaque full-cohort binding rejects a changed locator even after re-pinning runtime.
        from p7_guard_v3 import attest_runtime
        altered = read_pin(runtimes['RE2-TT'])
        first = next(iter(altered['cases'].values()))
        first['files']['metrics.parquet']['path'] = 'fixture/rehashed-wrong.parquet'
        changed = write('changed-runtime.json', altered)
        try:
            attest_runtime(result['protocol'], changed, independent['RE2-TT'], target / 'invalid-binding.json', granted=True)
        except Blocked:
            checks.append('R1_rehashed_locator_rejected')
        except ValueError:
            checks.append('R1_rehashed_locator_rejected')
        else:
            raise AssertionError('changed locator accepted')
    # The transfer path is exercised on generated bytes, replacing SSH with a local Python.
    fixture_file = target / 'source.txt'
    fixture_file.write_bytes(b'GENERATED-013-TRANSFER\n' * 10000)
    files = {'data/locked/fixture/opaque/file.txt': (fixture_file, ref(fixture_file))}
    def local_args(host, command):
        parts = shlex.split(command)
        assert parts[:3] == ['python3', '-B', '-c']
        return [sys.executable, '-B', '-c', parts[3]]
    with patch.object(launch, 'ssh_args', side_effect=local_args):
        value = launch.transfer('synthetic', files, str(target / 'destination'), 'fixture-transfer-only-003.json')
        assert value['PASS'] and value['bytes'] == fixture_file.stat().st_size
    checks.append('stream_staging_hash_verified_on_generated_bytes')
    atomic(target / 'summary.json', dict(PASS=True, checks=checks, scope='synthetic activation only; real G3/main remains false'))
    print(json.dumps(dict(PASS=True, checks=len(checks))))


if __name__ == '__main__':
    main()
